// Energy & Smart Grid AI Reasoning Node
const complaint = $('Webhook: Receive Electricity Complaint').first().json.body || {};
const feederData = $('HTTP Request: Smart Grid & Feeder Telemetry').first().json || {};
const history = $('Database: Check Feeder Complaint History').first().json || {};

const desc = complaint.description || '';
const textCorpus = (complaint.issue_type + ' ' + desc).toLowerCase();
const address = complaint.location?.address || 'Outer Ring Road Service Lane, Munirka';
const lat = complaint.location?.latitude || 28.5583;
const lng = complaint.location?.longitude || 77.1706;
const feederId = feederData.feeder_id || 'FDR-MUNIRKA-15';
const breakerStatus = feederData.breaker_status || 'NORMAL';

// Analyze issue type
const isStreetlight = textCorpus.includes('streetlight') || textCorpus.includes('dark') || textCorpus.includes('light');
const isOutage = textCorpus.includes('power cut') || textCorpus.includes('blackout') || breakerStatus === 'TRIPPED';
const isSparking = textCorpus.includes('spark') || textCorpus.includes('explosion') || textCorpus.includes('smoke');

// Determine Priority
let priority = 'MEDIUM';
let issueCategory = 'STREETLIGHT_OUTAGE';

if (isSparking) {
  priority = 'CRITICAL';
  issueCategory = 'TRANSFORMER_ELECTRICAL_FIRE_HAZARD';
} else if (isStreetlight && (textCorpus.includes('ring road') || textCorpus.includes('highway') || textCorpus.includes('arterial'))) {
  priority = 'HIGH'; // Dark arterial road is serious public safety & crime risk
  issueCategory = 'MAJOR_CORRIDOR_STREETLIGHT_FAILURE';
} else if (isOutage) {
  priority = 'HIGH';
  issueCategory = 'SUBSTATION_FEEDER_TRIP';
}

// Maintenance recommendations
const recommendations = [
  `Dispatch Utility Lineman Quick Response Vehicle to ${address} (Substation: ${feederData.substation || 'Local 66/11kV'}).`,
  `Inspect circuit breakers and underground cable line for suspected fault: ${feederData.suspected_fault || 'Cable insulation degradation'}.`
];

if (isStreetlight) {
  recommendations.push(`Check dusk-to-dawn automated photocell controller and replace blown phase fuses on Circuits: ${(feederData.affected_streetlight_circuits || ['CKT-A']).join(', ')}.`);
  recommendations.push('Coordinate with Traffic Police for temporary mobile lighting mast if repair takes > 4 hours.');
}
if (breakerStatus === 'TRIPPED') {
  recommendations.push('Conduct megger insulation resistance test before re-energizing tripped 11kV vacuum circuit breaker.');
}

const output = {
  incident_id: 'ENG-INC-' + Date.now(),
  complaint_id: complaint.complaint_id || 'CMP-ENG-006',
  source_agent: 'energy_management_agent',
  electricity_report: `Electrical infrastructure disruption identified: ${issueCategory}. Substation Feeder: ${feederId} (Status: ${breakerStatus}). Outage span: ~${feederData.estimated_outage_length_meters || 1600}m. Repeated history on line: ${history.matched_count || 0} recent tickets. Assessed Priority: ${priority}.`,
  affected_area: {
    address: address,
    feeder_id: feederId,
    substation: feederData.substation || 'Munirka Substation',
    latitude: lat,
    longitude: lng
  },
  priority: priority,
  issue_type: issueCategory,
  maintenance_recommendations: recommendations,
  public_safety_impact: isStreetlight || isSparking,
  escalate_to_command: priority === 'CRITICAL' || priority === 'HIGH',
  command_alert_headline: `[ENERGY ALERT - ${priority}] ${issueCategory} on Feeder ${feederId}`
};

return output;
